SELECT

FROM members m
WHERE 1 = 1

    AND m.member_status = #{cursor.memberStatus}


    AND (
        m.login_id LIKE CONCAT('%', #{cursor.keyword}, '%')
        OR m.name LIKE CONCAT('%', #{cursor.keyword}, '%')
        OR m.nickname LIKE CONCAT('%', #{cursor.keyword}, '%')
        OR m.email LIKE CONCAT('%', #{cursor.keyword}, '%')
    )


    AND m.member_id < #{cursor.cursorMemberId}

ORDER BY m.member_id DESC
LIMIT #{cursor.size}

SELECT

FROM members m
WHERE m.member_id = #{memberId}
